    ("en_US", "LOC_MPT_BALANCE_NAME", "Multiplayer Balance"),
    ("en_US", "LOC_MPT_BALANCE_DESC", "Balance changes for competitive multiplayer: civilizations, leaders, units, governments, wonders, resources, pantheons, mementos and victories. Added by Multiplayer Toolkit."),
    ("en_US", "LOC_MPT_BALANCE_ON_NAME", "On"),
