    ("en_US", "LOC_MPT_BALANCE_OFF_NAME", "Off"),
    ("en_US", "LOC_MPT_BALANCE_OFF_DESC", "Use Civilization VII's own balance."),
-- Victory Threshold setup option
    ("en_US", "LOC_MBM_VICTORY_THRESHOLD_SCALE_NAME", "Victory Threshold Scaling"),
    ("en_US", "LOC_MBM_VICTORY_THRESHOLD_SCALE_DESCRIPTION", "Changes the score multiplier required for Culture, Economic, and Military victories. Science remains fixed at 100 Innovation."),
