    ("en_US",  "LOC_TURNPHASE_SIMULTANEOUS_DESC",   "Default setting for standard simultaneous turns"),
    ("en_US",  "LOC_TURNPHASE_SIMULTANEOUS_MBG",   "MBG Dynamic Timer"),
    ("en_US",  "LOC_TURNPHASE_SIMULTANEOUS_MBG_DESC",   "MBm dynamic timer (30s base + 3s per city + 2s per unit)[n]Make sure base game dynamic timer is set"),
    ("en_US",  "LOC_TURNPHASE_DYNAMIC",   "Dynamic"),
    ("en_US",  "LOC_GAME_TURNPHASE_DESC",   "Advanced option for dynamic timer"),

    ("en_US",  "LOC_MBM_STANDARD",   "Standard"),
    ("en_US",  "LOC_MBM_STANDARD_DESC",   "45s base + 5s per city + 1s per unit"),

    ("en_US",  "LOC_MBM_BLITZ",   "Blitz"),
    ("en_US",  "LOC_MBM_BLITZ_DESC",   "30s base + 3s per city + 1s per unit"),

