    ("en_US",  "LOC_MBM_COP_DESC",   "35s base + 4s per city + 1s per unit"),

-- Leaders
    -- Alexander
    ("en_US", "LOC_LEADER_ALEXANDER_DESCRIPTION", "[TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with a [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonder[/TIP] get +10% [icon:YIELD_PRODUCTION] Production and [icon:YIELD_CULTURE] Culture, doubled in captured Settlements. +1 [icon:NAR_REW_COMBAT] Combat Strength for Unique Military Units for every Settlement with a Wonder, up to +5. +2 [icon:MILITARY_VP] Dominion for every [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with a Wonder other than your Capital. [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] converted into Cities are renamed after Alexander."),
    ("en_US", "LOC_TRAIT_LEADER_ALEXANDER_ABILITY_DESCRIPTION", "[BLIST][LI][TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with a [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonder[/TIP] get [B]+10% [icon:YIELD_PRODUCTION] Production[/B] and [B][icon:YIELD_CULTURE] Culture[/B], doubled in [B]captured Settlements[/B] from any Age.[LI][B]+1 [icon:NAR_REW_COMBAT] Combat Strength[/B] for [B]Unique Military Units[/B] for every Settlement with a Wonder, up to +5.[LI][B]+2 [icon:MILITARY_VP] Dominion[/B] for every [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with a Wonder other than your Capital.[LI][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] converted into [icon:YIELD_CITIES] [B]Cities[/B] are renamed after Alexander.[/LIST]"),
    -- Amina 
    ("en_US",  "LOC_LEADER_AMINA_DESCRIPTION",   "+1 [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]. +2 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for each [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]. +3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] in Plains and Desert."),
    ("en_US",  "LOC_TRAIT_LEADER_AMINA_ABILITY_DESCRIPTION",   "[BLIST][LI]+1 [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].[LI]+2 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for each [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].[LI]+3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] in Plains and Desert.[/BLIST]"),
    -- Ashoka WC
    ("en_US",  "LOC_LEADER_ASHOKA_ALT_DESCRIPTION",   "+1[icon:YIELD_PRODUCTION] Production in [B]Settlements [/B] for every 5 excess [icon:YIELD_HAPPINESS] Happiness. +10% [icon:YIELD_PRODUCTION] Production in Settlements not founded by you. Declaring a [icon:WAR] Formal War grants a [icon:CELEBRATION] Celebration. +5 [icon:NAR_REW_COMBAT] Combat Strength against [icon:CITY_FORTIFIED] Fortified Districts for all Units during a [icon:CELEBRATION] Celebration."),
    ("en_US",  "LOC_TRAIT_LEADER_ASHOKA_ALT_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+1[icon:YIELD_PRODUCTION] Production in [B]Settlements [/B] [/B]for every [B]5 [/B]excess [icon:YIELD_HAPPINESS] [B]Happiness [/B].[LI][B]+10% [icon:YIELD_PRODUCTION] Production [/B]in Settlements not founded by you.[LI]Declaring a [icon:WAR] [B]Formal War [/B]grants a [icon:CELEBRATION] [B]Celebration[/B].[LI][B]+5 [icon:NAR_REW_COMBAT] Combat Strength[/B] against [icon:CITY_FORTIFIED] [B]Fortified Districts[/B] for all Units during a [icon:CELEBRATION] [B]Celebration[/B].[/LIST]"),
    -- Ashoka WR
    ("en_US",  "LOC_LEADER_ASHOKA_DESCRIPTION",   "+1 [icon:YIELD_FOOD] Food in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] for every 5 excess [icon:YIELD_HAPPINESS] Happiness. +10% [icon:YIELD_FOOD] Food in Happy [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] during a [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP], or 15% in Joyous Settlements, or 20% in Ecstatic Settlements. All [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] gain a +0.5 [icon:YIELD_HAPPINESS] Happiness adjacency for each adjacent [icon:CITY_RURAL] Improvement."),
    ("en_US",  "LOC_TRAIT_LEADER_ASHOKA_ABILITY_DESCRIPTION",   "[BLIST][LI]+1 [icon:YIELD_FOOD] Food in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] for every 5 excess [icon:YIELD_HAPPINESS] Happiness.[LI]+10% [icon:YIELD_FOOD] Food in Happy [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] during a [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP], or 15% in Joyous Settlements, or 20% in Ecstatic Settlements.[LI]All [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] gain a [B]+0.5 [icon:YIELD_HAPPINESS] Happiness adjacency[/B] for each adjacent [icon:CITY_RURAL] Improvement.[/BLIST]"),
   -- Catherine
    ("en_US",  "LOC_LEADER_CATHERINE_DESCRIPTION",   "+4 [icon:YIELD_CULTURE] Culture per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on displayed [icon:GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Works[/TIP]. [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP] with [icon:GREATWORK] Great Work slots gain 1 additional slot. [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] settled in Tundra gain [icon:YIELD_SCIENCE] Science equal to 25% of their [icon:YIELD_CULTURE] Culture per turn.]"),
    ("en_US",  "LOC_TRAIT_LEADER_CATHERINE_ABILITY_DESCRIPTION",   "[BLIST][LI]+4 [icon:YIELD_CULTURE] Culture per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on displayed [icon:GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Works[/TIP].[LI][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP] with [icon:GREATWORK] Great Work slots gain 1 additional slot.[LI][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] settled in Tundra gain [icon:YIELD_SCIENCE] Science equal to 25% of their [icon:YIELD_CULTURE] Culture per turn.[/BLIST]"),
    -- Friedrich Bar
    ("en_US",  "LOC_LEADER_FRIEDRICH_ALT_DESCRIPTION",   "Gain a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] when you capture a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] for the first time. [B]+3 [icon:YIELD_PRODUCTION] Production[/B] per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on displayed [icon:NAR_REW_GREATWORK] Great Works. Gain an [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry Unit[/TIP] in your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] when you complete a [TIP:LOC_PEDIA_CONCEPTS_MASTERY_TOOLTIP]Civic Mastery[/TIP], and in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] where you construct a [icon:YIELD_CULTURE] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture Building[/TIP]."),
    ("en_US",  "LOC_TRAIT_LEADER_FRIEDRICH_ALT_ABILITY_DESCRIPTION",   "[BLIST][LI]Gain a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] when you capture a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] for the first time.[LI]+3 [icon:YIELD_PRODUCTION] Production per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on displayed [icon:NAR_REW_GREATWORK] Great Works.[LI]Gain an [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry Unit[/TIP] in your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] when you complete a [TIP:LOC_PEDIA_CONCEPTS_MASTERY_TOOLTIP]Civic Mastery[/TIP], and in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] where you construct a [icon:YIELD_CULTURE] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture Building[/TIP].[/LIST]"),
    -- Hatshepsut
    ("en_US",  "LOC_LEADER_HATSHEPSUT_DESCRIPTION",   "+1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold[/B] per Age on [icon:RADIAL_RESOURCES] [B]Resource[/B]. +15% [icon:YIELD_PRODUCTION] Production towards constructing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP]."),
    ('en_US',  'LOC_TRAIT_LEADER_HATSHEPSUT_ABILITY_DESCRIPTION',   '[BLIST][LI][B]+1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold[/B] per Age on [icon:RADIAL_RESOURCES] [B]Resource[/B].[LI][B]+15% [icon:YIELD_PRODUCTION] Production [/B]towards constructing [icon:CITY_BUILDING_LIST] [B]Buildings [/B]and [icon:WONDER] [B]Wonders [/B]in [icon:YIELD_CITIES] [B]Cities [/B]adjacent to [B]Navigable Rivers[/B].[/LIST]'),
    -- Himiko HS
    ("en_US",  "LOC_LEADER_HIMIKO_ALT_DESCRIPTION",   "+2 [icon:YIELD_HAPPINESS][icon:YIELD_HAPPINESS] Happiness per Age on [icon:YIELD_HAPPINESS] Happiness and [icon:YIELD_DIPLOMACY] Diplomacy Buildings, doubled if a Building is both. +50% [icon:YIELD_PRODUCTION] Production towards constructing [icon:YIELD_HAPPINESS] Happiness and [icon:YIELD_DIPLOMACY] Diplomacy Buildings, doubled if a Building is both. +15% [icon:YIELD_CULTURE] Culture, or +30% [icon:YIELD_CULTURE] Culture while in a [icon:CELEBRATION] Celebration, but -5% [icon:YIELD_SCIENCE] Science (regardless of celebration)."),
    ("en_US",  "LOC_TRAIT_LEADER_HIMIKO_ALT_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+2 [icon:YIELD_HAPPINESS] Happiness [/B]per Age on [icon:YIELD_HAPPINESS] [B]Happiness [/B]and [icon:YIELD_DIPLOMACY] [B]Diplomacy Buildings[/B], doubled if a [B]Building[/B] is both.[LI][B]+50% [icon:YIELD_PRODUCTION] Production [/B]towards constructing [icon:YIELD_HAPPINESS] [B]Happiness[/B] and [icon:YIELD_DIPLOMACY] [B]Diplomacy Buildings[/B], doubled if a [B]Building[/B] is both.[LI][B]+15% [icon:YIELD_CULTURE] Culture[/B], or [B]+30% [icon:YIELD_CULTURE] Culture[/B] while in a [icon:CELEBRATION] [B]Celebration[/B], but [B]-5% [icon:YIELD_SCIENCE] Science[/B] (regardless of celebration).[/LIST]"),
    --Ganguis
    ("en_US",  "LOC_LEADER_GENGHIS_KHAN_DESCRIPTION",   "+3 [icon:NAR_REW_COMBAT] Combat Strength for Cavalry Units. [icon:UNIT_ARMY_COMMANDER]Army Commanders have +1 [icon:Action_Move] Movement even when no Units are packed into them. Once per Age, [icon:UNIT_ARMY_COMMANDER] Army Commanders can use the Convert Independents Action to convert adjacent [icon:INDEPENDENT_POWER] Independent Military Units to your control. [B]-1 [icon:YIELD_GOLD][/B] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] per age on [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Units[/TIP]"),
    ("en_US",  "LOC_TRAIT_LEADER_GENGHIS_KHAN_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+3 [icon:NAR_REW_COMBAT] Combat Strength [/B]for [B]Cavalry Units[/B].[LI][icon:UNIT_ARMY_COMMANDER] [B]Army Commanders [/B]have [B]+1 [icon:Action_Move] Movement [/B]even when no Units are packed into them.[LI]Once per Age, [icon:UNIT_ARMY_COMMANDER] [B]Army Commanders [/B]can use the [B]Convert Independents Action[/B] to convert adjacent [icon:INDEPENDENT_POWER] [B]Independent Military Units [/B]to your control.[LI][B]-1 [icon:YIELD_GOLD][/B] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] per age on [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Units[/TIP][/LIST]"),
    ("en_US",  "LOC_ABILITY_GENGHIS_KHAN_ARMY_COMMANDER_DESCRIPTION",   "+3 [icon:NAR_REW_COMBAT] Combat Strength for Cavalry Units. [icon:UNIT_ARMY_COMMANDER] Army Commanders have +1 [icon:Action_Move] Movement even when no Units are packed into them. Once per Age, [icon:UNIT_ARMY_COMMANDER] Army Commanders can use the Convert Independents Action to convert adjacent [icon:INDEPENDENT_POWER] Independent Military Units to your control. [B]-1 [icon:YIELD_GOLD][/B] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] per age on [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Units[/TIP]"),
    ("en_US",  "LOC_ABILITY_GENGHIS_KHAN_COMMAND_RADIUS_COMBAT_DESCRIPTION",   "+0 CS [icon:YIELD_HAPPINESS]"),
    -- Gilgamesh
    ("en_US",  "LOC_LEADER_GILGAMESH_DESCRIPTION",   "When one of your Military Units defeats an enemy Unit, gain [icon:YIELD_DIPLOMACY] Influence equal to 50% of the defeated Unit's [icon:NAR_REW_COMBAT] Combat Strength. All basic Endeavors are automatically unlocked. Endeavors with Allies don’t count against the limit of having one Endeavor of a given type active at a time. Allies can support your Endeavors for free."),
    ("en_US",  "LOC_TRAIT_LEADER_GILGAMESH_ABILITY_DESCRIPTION",   "[BLIST][LI]When one of your Military Units defeats an enemy Unit, gain [B][icon:YIELD_DIPLOMACY] Influence[/B] equal to 50% of the defeated Unit's [icon:NAR_REW_COMBAT] Combat Strength.[LI]All basic Endeavors are automatically unlocked. Endeavors with Allies don’t count against the limit of having one Endeavor of a given type active at a time. Allies can support your Endeavors for free. [/LIST]"),
    -- Jose Rizal
    ("en_US",  "LOC_LEADER_JOSE_RIZAL_DESCRIPTION",   "When gaining rewards from a [icon:NAR_REW_DEFAULT] Narrative Event or entering a [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP], gain an additional 20 [icon:YIELD_CULTURE] Culture, [icon:YIELD_GOLD] Gold, and [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] (On Online Speed). Has additional [icon:NAR_REW_DEFAULT] Narrative Events. +50% [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP] duration. +50% [icon:YIELD_HAPPINESS] Happiness towards [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebrations[/TIP]."),
    ("en_US",  "LOC_TRAIT_LEADER_JOSE_RIZAL_ABILITY_DESCRIPTION",   "[BLIST][LI]When gaining rewards from a [icon:NAR_REW_DEFAULT] Narrative Event or entering a [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP], gain an additional 20 [icon:YIELD_CULTURE] Culture, [icon:YIELD_GOLD] Gold, and [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] (On Online Speed)[LI]Has additional [icon:NAR_REW_DEFAULT] Narrative Events.[LI]+50% [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP] duration.[LI]+50% [icon:YIELD_HAPPINESS] Happiness towards [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebrations[/TIP].[/BLIST]"),
    -- Elizabeth
    ("en_US", "LOC_LEADER_ELIZABETH_DESCRIPTION", "Unlimited [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] Range. When you found a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] on a different [TIP:LOC_PEDIA_CONCEPTS_CONTINENT_TOOLTIP]Continent[/TIP] than your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP], receive a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP]. [B]+2 [icon:Action_Move] Movement[/B] to [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP], [TIP:LOC_PEDIA_CONCEPTS_EMBARK_TOOLTIP]Embarked[/TIP] [icon:UNIT_SETTLER] Settlers, and Embarked [icon:UNIT_MERCHANT] Merchants. [icon:UNIT_MERCHANT] Merchants and [icon:UNIT_SETTLER] Settlers are 15% cheaper to purchase [B]-2 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to Land Combat Units But [B]+2 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to Naval Combat Units."),
    ("en_US", "LOC_TRAIT_LEADER_ELIZABETH_ABILITY_DESCRIPTION", "[BLIST][LI]Unlimited [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] Range.[LI]When you found a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] on a different [TIP:LOC_PEDIA_CONCEPTS_CONTINENT_TOOLTIP]Continent[/TIP] than your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP], receive a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP].[LI]+2 [icon:Action_Move] Movement to [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP], [TIP:LOC_PEDIA_CONCEPTS_EMBARK_TOOLTIP]Embarked[/TIP] [icon:UNIT_SETTLER] Settlers, and Embarked [icon:UNIT_MERCHANT] Merchants. [icon:UNIT_MERCHANT] Merchants and [icon:UNIT_SETTLER] Settlers are 15% cheaper to purchase.[LI]-2 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to Land Combat Units But [B]+2 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to Naval Combat Units.[/LIST]"),
    -- George Washington
    ("en_US", "LOC_LEADER_WASHINGTON_DESCRIPTION", "Gain a Migrant in your Capital when entering a Celebration. Gain 1 additional Social Policy slot. Bill of Rights unlocks at Discipline and Continental Ambition unlocks at Code of Laws. For each Policy, but not Tradition, slotted into your Government, get +1 Food per Age in Towns and +2 Happiness per Age in Cities."),
    ("en_US", "LOC_TRAIT_LEADER_WASHINGTON_ABILITY_DESCRIPTION", "[BLIST][LI]Gain a [icon:UNIT_MIGRANT] Migrant in your Capital when entering a Celebration.[LI]Gain 1 additional [icon:SOCIAL_POLICY] Social Policy slot.[LI]Bill of Rights unlocks at Discipline and Continental Ambition unlocks at Code of Laws.[LI]For each Policy, but not Tradition, slotted into your Government, get +1 [icon:YIELD_FOOD] Food per Age in Towns and +2 [icon:YIELD_HAPPINESS] Happiness per Age in Cities.[/LIST]"),
    -- Lafayette
    ("en_US", "LOC_TRAIT_LEADER_LAFAYETTE_ABILITY_DESCRIPTION", "[BLIST][LI]Gains a unique [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] called Reform, which grants an additional [icon:NAR_REW_TRADITION_SLOT] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slot. Supporting this [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] also grants the other Leader an additional [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slot, otherwise they are granted a [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP] slot.[LI]+1 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for Land Units for every [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], but not [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], slotted in the [icon:GOVERNMENT] Government, up to [b]+4[/B][LI]+1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_HAPPINESS] Happiness per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP], doubled in [TIP:LOC_PEDIA_CONCEPTS_DISTANT_LANDS_TOOLTIP]Distant Lands[/TIP].[/BLIST]"),
    ("en_US", "LOC_ABILITY_LAFAYETTE_COMBAT_DESCRIPTION", "+{1_Value} Combat Strength for Land Units for every Tradition slotted into the Government, up to [b]+4[/B]"),
    --Machiavelli
    ('en_US',  'LOC_TRAIT_LEADER_MACHIAVELLI_ABILITY_DESCRIPTION',   '[BLIST][LI]+1 [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [B]Settlments[/B].[LI]Gains 50 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] when your [icon:DIPLOMATIC_ACTION] Diplomatic Action proposals are accepted, or 100 [icon:YIELD_GOLD] Gold when they are rejected.[LI]Ignores [icon:RELATIONSHIP] Relationship requirements for declaring [icon:WAR] Formal Wars.[LI]Can Levy Troops from [icon:CITYSTATE] City-States you are not [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of.[/BLIST]'),
    ('en_US',  'LOC_LEADER_MACHIAVELLI_DESCRIPTION',   '+1 [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [B]Settlments[/B]. Gains 50 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] when your [icon:DIPLOMATIC_ACTION] Diplomatic Action proposals are accepted, or 100 [icon:YIELD_GOLD] Gold when they are rejected. Ignores [icon:RELATIONSHIP] Relationship requirements for declaring [icon:WAR] Formal Wars. Can Levy Troops from [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-States[/TIP] you are not [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of.'),
-- Napoleon Emperor
    ("en_US", "LOC_LEADER_NAPOLEON_DESCRIPTION", "All basic [icon:SANCTIONS] Sanctions are automatically unlocked. +50% [icon:YIELD_DIPLOMACY] Influence towards initiating [icon:SANCTIONS] Sanctions. +5 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold per Age for each Leader you have an active [icon:SANCTIONS] Sanction on, except Denouncement. +1 [icon:NAR_REW_COMBAT] Combat Strength for Land Units for every [icon:PLAYER_RELATIONSHIP_UNFRIENDLY] Unfriendly or [icon:PLAYER_RELATIONSHIP_HOSTILE] Hostile Civilization, up to +4."),
    ("en_US", "LOC_TRAIT_LEADER_NAPOLEON_ABILITY_DESCRIPTION", "[BLIST][LI]All basic [icon:SANCTIONS] [B]Sanctions[/B] are automatically unlocked.[LI][B]+50% [icon:YIELD_DIPLOMACY] Influence[/B] towards initiating [icon:SANCTIONS] [B]Sanctions[/B].[LI][B]+5 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold per Age[/B] for each Leader you have an active [icon:SANCTIONS] [B]Sanction[/B] on, except [B]Denouncement[/B].[LI][B]+1 [icon:NAR_REW_COMBAT] Combat Strength[/B] for [B]Land Units[/B] for every [icon:PLAYER_RELATIONSHIP_UNFRIENDLY] Unfriendly or [icon:PLAYER_RELATIONSHIP_HOSTILE] Hostile Civilization, up to [B]+4[/B].[/BLIST]"),  
    -- Simon Bolivar
    ("en_US", "LOC_LEADER_BOLIVAR_DESCRIPTION", "+20% [icon:YIELD_DIPLOMACY] Influence towards adding [icon:WAR_SUPPORT] [TIP:LOC_PEDIA_CONCEPTS_WAR_SUPPORT_TOOLTIP]War Support[/TIP]. When you conquer a Settlement for the first time it can purchase 1 [icon:CITY_BUILDING_LIST] Building or [icon:CITY_RURAL] Improvement for free. [icon:YIELD_ANGRY] Unrest does not prevent Purchasing."),
    ("en_US", "LOC_TRAIT_LEADER_BOLIVAR_ABILITY_DESCRIPTION", "[BLIST][LI][B]+20% [icon:YIELD_DIPLOMACY] Influence[/B] towards adding [icon:WAR_SUPPORT] [TIP:LOC_PEDIA_CONCEPTS_WAR_SUPPORT_TOOLTIP]War Support[/TIP].[LI]When you conquer a Settlement for the first time, the Settlement can [B]purchase 1 [icon:CITY_BUILDING_LIST] Building or [icon:CITY_RURAL] Improvement for free[/B].[LI][icon:YIELD_ANGRY] [B]Unrest[/B] does not prevent Purchasing.[/LIST]"),
    -- Tecumseh
    ("en_US",  "LOC_LEADER_TECUMSEH_DESCRIPTION",   "+1 [icon:YIELD_FOOD] Food and [icon:YIELD_PRODUCTION] Production per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] for every [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of. +1 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for Infantry and Ranged Units for every [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of, up to +4. +2 [icon:MILITARY_VP] Dominion for every [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of."),
    ("en_US",  "LOC_TRAIT_LEADER_TECUMSEH_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:YIELD_FOOD] Food[/B] per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [B][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP][/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] per Age in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.[LI][B]+1 [icon:NAR_REW_COMBAT] Combat Strength[/B] for all [B][TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry[/TIP][/B] and [B][TIP:LOC_PEDIA_CONCEPTS_RANGED_UNITS_TOOLTIP]Ranged units[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of, up to [B]+4[/B].[LI][B]+2 [icon:MILITARY_VP] [TIP:LOC_PEDIA_CONCEPTS_DOMINION_TOOLTIP]Dominion[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.[LI]All [B][icon:INDEPENDENT_POWER] [TIP:LOC_PEDIA_CONCEPTS_INDEPENDENT_POWER_TOOLTIP]Independent Powers[/TIP][/B] start [B][icon:PLAYER_RELATIONSHIP_FRIENDLY] Friendly[/B] with you.[/BLIST]"),
    ("en_US",  "LOC_ABILITY_TECUMSEH_SUZERAIN_DESCRIPTION",   "+1 [icon:NAR_REW_COMBAT] Combat Strength for every [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of, to a maximum of +4."),
    -- Tubman
    ("en_US",  "LOC_LEADER_HARRIET_TUBMAN_DESCRIPTION",   "Gain [B]+5 [icon:NAR_REW_COMBAT] Combat Strength [/B]on all units in friendly terrain. +100% [icon:YIELD_DIPLOMACY] Influence towards initiating [icon:ESPIONAGE] [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Actions. Gain a Migrant in the Capital whenever you complete an [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Action without being detected. [icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_VEGETATED_TERRAIN_TOOLTIP]Vegetated Terrain[/TIP] does not end Unit [icon:Action_Move] Movement."),
    ("en_US",  "LOC_TRAIT_LEADER_HARRIET_TUBMAN_ABILITY_DESCRIPTION",   "[BLIST][LI]Gain [B]+5 [icon:NAR_REW_COMBAT] Combat Strength [/B]on all units in friendly terrain.[LI]+100% [icon:YIELD_DIPLOMACY] Influence towards initiating [icon:ESPIONAGE] [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Actions. Gain a Migrant in the Capital whenever you complete an [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Action without being detected.[LI][icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_VEGETATED_TERRAIN_TOOLTIP]Vegetated Terrain[/TIP] does not end Unit [icon:Action_Move] Movement.[/BLIST]"),    
    -- Trung
    ("en_US",  "LOC_LEADER_TRUNG_TRAC_DESCRIPTION",   "Gain the Unique [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commander[/TIP] Trung Nhi after obtaining your first Land [TIP:LOC_PEDIA_CONCEPTS_MILITARY_UNIT_TOOLTIP]Military Unit[/TIP] of the [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP]. [icon:UNIT_ARMY_COMMANDER] Trung Nhi persists across [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] Transitions, and begins with 2 [icon:NAR_REW_PROMOTION] Promotions in Exploration Advanced Starts or 3 [icon:NAR_REW_PROMOTION] Promotions in Modern Advanced Starts, and has a unique  [TIP:LOC_PEDIA_CONCEPTS_PROMOTION_TOOLTIP]Promotion[/TIP] Tree. +20% [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_EXPERIENCE_TOOLTIP]Commander Experience[/TIP]. +10% [icon:YIELD_SCIENCE] Science in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] in Tropical. This is doubled while in [icon:WAR] War."),
    ("en_US",  "LOC_TRAIT_LEADER_TRUNG_TRAC_ABILITY_DESCRIPTION",   "[BLIST][LI]Gain the Unique [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commander[/TIP] Trung Nhi after obtaining your first Land [TIP:LOC_PEDIA_CONCEPTS_MILITARY_UNIT_TOOLTIP]Military Unit[/TIP] of the [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP]. [icon:UNIT_ARMY_COMMANDER] Trung Nhi persists across [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] Transitions, and begins with 2 [icon:NAR_REW_PROMOTION] Promotions in Exploration Advanced Starts or 3 [icon:NAR_REW_PROMOTION] Promotions in Modern Advanced Starts, and has a unique  [TIP:LOC_PEDIA_CONCEPTS_PROMOTION_TOOLTIP]Promotion[/TIP] Tree.[LI]+20% [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_EXPERIENCE_TOOLTIP]Commander Experience[/TIP].[LI]+10% [icon:YIELD_SCIENCE] Science in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] in Tropical. This is doubled while in [icon:WAR] War.[/BLIST]"),
    -- Toyotomi
    ("en_US",  "LOC_LEADER_TOYOTOMI_HIDEYOSHI_DESCRIPTION",   "[TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] gain +5 [icon:NAR_REW_COMBAT] Combat Strength against opposing Units receive -5 [icon:NAR_REW_COMBAT] Combat Strength when defending. Your Units [b][icon:Action_Heal] Heal[/b] an additional 5 HP, this is doubled if on a [b][icon:YIELD_CULTURE] Culture [/b][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] or [B][icon:WONDER] Wonder[/B]. [b]+50% [icon:YIELD_PRODUCTION] Production[/b] towards [b][icon:YIELD_CULTURE] Culture Buildings[/b]. This is [b]doubled[/b] in [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Captured Cities[/TIP] from any Age. "),
    ("en_US",  "LOC_TRAIT_LEADER_TOYOTOMI_HIDEYOSHI_ABILITY_DESCRIPTION",   "[BLIST][LI][TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] gain [B]+5 [icon:NAR_REW_COMBAT] Combat Strength[/B] against opposing Units receive [B]-5 [icon:NAR_REW_COMBAT] Combat Strength[/B] when defending.[LI]Your Units [b][icon:Action_Heal] Heal[/b] an additional 5 HP, this is doubled if on a [b][icon:YIELD_CULTURE] Culture [/b][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] or [B][icon:WONDER] Wonder[/B]. [LI][b]+50% [icon:YIELD_PRODUCTION] Production[/b] towards [b][icon:YIELD_CULTURE] Culture Buildings[/b]. This is [b]doubled[/b] in [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Captured Cities[/TIP] from any Age.[/LIST]"),
    ("en_US",  "MBM_TOYOTOMI_CS",   "Great Unifier"),

