-- Altar
    ('en_US', 'LOC_BUILDING_ALTAR_DESCRIPTION', '+3 [icon:YIELD_HAPPINESS] Happiness. Provides benefits and [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses based on your chosen [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_PANTHEON_TOOLTIP]Pantheon[/TIP]. Your Pantheon effect automatically carries over into future Ages. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP] Happiness [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse Building[/TIP]. Can be purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP].'),
    ('en_US', 'LOC_BUILDING_ALTAR_TOOLTIP', 'Effect: Provides benefits and [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses based on your chosen [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_PANTHEON_TOOLTIP]Pantheon[/TIP]. Your Pantheon effect automatically carries over into future Ages.[n][TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse Building[/TIP].[n][TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP].[n]Can be purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP].'),

-- religion
    ('en_US', 'LOC_BELIEF_BONUS_3_DESCRIPTION', '+3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_MILITARY_UNIT_TOOLTIP]Military Units[/TIP] in friendly [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] that follow this [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_RELIGION_TOOLTIP]Religion[/TIP].'),

-- Building cost scaling
    ('en_US', 'LOC_PEDIA_CONCEPTS_PAGE_CITY_1_CHAPTER_CONTENT_PARA_5', 'Remember that each Town you upgrade to a City beyond your Capital will increase non-Warehouse Building costs by 5% each.'),
    ('en_US', 'LOC_PEDIA_CONCEPTS_PAGE_BUILDINGS_1_CHAPTER_CONTENT_PARA_4', 'Non-Warehouse Buildings have scaling costs throughout the game. Their cost increases by 5% for each other non-Warehouse Building in the Settlement, as well as by 5% for each City you have beyond your Capital.'),

-- Military Victory
    ('en_US', 'LOC_MBM_RAZED_SETTLEMENT_DOMINION_NAME', 'Razed Settlements'),
    ('en_US', 'LOC_MBM_RAZED_SETTLEMENT_DOMINION_DESCRIPTION', '+2 [icon:MILITARY_VP] Dominion whenever you finish razing a Settlement.'),
    ('en_US', 'LOC_VICTORY_MILITARY_LONGFORM', 'To win a Military Victory, you must achieve military dominance against all other leaders. Military Victory points, called Dominion, are earned by controlling Settlements and by finishing the razing of captured Settlements. Controlled Settlements provide extra Dominion if they are Capitals, were conquered, are in the Distant Lands, or belonged to an opponent with an opposing Ideology.'),
    ('en_US', 'LOC_PEDIA_PAGE_VICTORY_MILITARY_MODERN_CHAPTER_CONTENT_PARA_2', 'Sources of Dominion:[BLIST][LI]Settlements you control: 2 points[LI]Original Capitals you control: 4 additional points[LI]Settlements you control in the Distant Lands: 1 additional point[LI]Settlements you have captured: 2 additional points[LI]Settlements captured from an Ideological opponent: 2 additional points[LI]Each Settlement you finish razing: 2 points[/LIST]'),
    ('en_US', 'LOC_VICTORIES_RULES_MILITARY', 'The [B]Military Victory[/B] is awarded to a leader when they achieve military dominance against all other leaders. This dominance is measured by [B]Dominion[/B], which is primarily a measure of [B]Settlements[/B].[NN]Each Settlement you control is worth [B]2 Dominion[/B]. Settlements can be worth additional Dominion as follows:[NN][BLIST][LI][B]Original Capital[/B]: +4 points[LI][B]Distant Lands[/B]: +1 point[LI][B]Captured[/B]: +2 points[LI][B]Captured from Ideological Opponent[/B]: +2 points[LI][B]Razed Settlement (when fully destroyed)[/B]: +2 points[/LIST]'),

    
-- Victories and Triumphs
    ('en_US', 'LOC_LEGACY_EX_MILITARISTIC_5_DESCRIPTION', '[B]+1 [icon:CULTURE_VP][/B] [TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]Tourism[/TIP] from all Fortifications.'),
    ('en_US', 'LOC_LEGACY_AQ_ECONOMIC_1_DESCRIPTION', '[B]+1 [icon:RADIAL_RESOURCES][/B] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in all [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP]. Assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_BONUS_RESOURCES_TOOLTIP]Bonus Resources[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] provide [B]+1 [icon:ECONOMIC_VP][/B] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] per turn.'),
    ('en_US', 'LOC_UNLOCK_AQ_ECONOMIC_1_DESCRIPTION', '[B]+1 [icon:RADIAL_RESOURCES][/B] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in all [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP]. Assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_BONUS_RESOURCES_TOOLTIP]Bonus Resources[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] provide [B]+1 [icon:ECONOMIC_VP][/B] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] per turn.'),
    ('en_US', 'LOC_LEGACY_EX_ECONOMIC_1_DESCRIPTION', '[B]+2 [icon:YIELD_GOLD][/B] for every assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP]. Assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_BONUS_RESOURCES_TOOLTIP]Bonus Resources[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] provide [B]+1 [icon:ECONOMIC_VP][/B] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] per turn.'),
    ('en_US', 'LOC_UNLOCK_EX_ECONOMIC_1_DESCRIPTION', '[B]+2 [icon:YIELD_GOLD][/B] for every assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP]. Assigned [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_BONUS_RESOURCES_TOOLTIP]Bonus Resources[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] provide [B]+1 [icon:ECONOMIC_VP][/B] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] per turn.'),
    ('en_US', 'LOC_LEGACY_AQ_MILITARISTIC_2_DESCRIPTION', '[B]+1 [icon:WAR_SUPPORT][/B] [TIP:LOC_PEDIA_CONCEPTS_WAR_SUPPORT_TOOLTIP]War Support[/TIP] on all Wars.'),
    ('en_US', 'LOC_UNLOCK_AQ_MILITARISTIC_2_DESCRIPTION', '[B]+1 [icon:WAR_SUPPORT][/B] [TIP:LOC_PEDIA_CONCEPTS_WAR_SUPPORT_TOOLTIP]War Support[/TIP] on all Wars.'),
    ('en_US', 'LOC_MOD_AQ_GOLD_BUILDING_VP', '+1 [icon:ECONOMIC_VP] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] per turn from [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Gold Buildings[/TIP].'),
    ('en_US', 'LOC_MBM_VICTORY_TRACKER_ABUNDANCE_TOWNS_NAME', 'Abundance: Bonus Resources in Towns'),
    ('en_US', 'LOC_MBM_VICTORY_TRACKER_ABUNDANCE_CITY_OFFSET_NAME', 'Abundance City Offset'),
    ('en_US', 'LOC_PEDIA_PAGE_VICTORY_ECONOMIC_MODERN_CHAPTER_CONTENT_PARA_2', 'The following contribute to your GDP each turn:[BLIST][LI]Slotted City and Bonus Resources in Cities (Not Towns): 1 per turn after Researching The Wheel.[LI]Imported Resources Slotted in Cities (Not Towns): 1 per turn after researching Skilled Trades.[LI]Returned Treasure Convoys: 20 points per Cargo (Scaled by game speed).[LI]Slotted Factory Resources in Settlements (Cities and Towns): 2 per turn after Researching Mass Production.[LI]Gold Buildings from the current Age: 1 per turn after Researching Currency.[/BLIST]'),
    ('en_US', 'LOC_VICTORIES_RULES_ECONOMIC', 'The [B]Economic Victory[/B] is awarded to a leader when they achieve economic dominance against all other leaders. This dominance is measured by [B]GDP[/B]. The following contribute to your GDP each turn:[NN][BLIST][LI][B]Gold Buildings[/B]: +1 GDP per turn for each Gold Building from the current Age after Researching Currency.[LI][B]City Resources and Bonus Resources[/B]: +1 GDP per turn for each City and Bonus Resource assigned to a City (not a Town) after Researching The Wheel.[LI][B]Imported Resources[/B]: +1 additional GDP per turn for each Resource imported via a [B]Trade Route[/B] and assigned to a City (not a Town) after Researching Skilled Trades.[LI][B]Treasure Convoys[/B]: 20 GDP per Cargo for each returned Treasure Convoy. This amount scales by Game Speed.[LI][B]Factory Resources[/B]: +3 GDP per turn for each Factory Resource assigned to a City or Town.[/LIST][NN]Certain Triumphs also provide GDP.'),

-- Attribute-tree
    ("en_US", "LOC_MOD_ATTRIBUTE_CULTURAL_06_DESCRIPTION", "+2 [icon:YIELD_CULTURE] Culture per Age from displayed [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Works[/TIP]. Immediately gain a free Great Work and gain another at the start of each Age."),
    ("en_US", "LOC_MOD_ATTRIBUTE_POLITICAL_02_DESCRIPTION", "+1 [icon:YIELD_DIPLOMACY] Influence per Age in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]."),
    ("en_US", "LOC_MOD_ATTRIBUTE_POLITICAL_05_DESCRIPTION", "+25% [icon:YIELD_DIPLOMACY] Influence towards sending, supporting, or rejecting [icon:DIPLOMATIC_ACTION] Diplomatic Actions."),
    ("en_US", "LOC_MOD_ATTRIBUTE_POLITICAL_07_DESCRIPTION", "+4 [icon:YIELD_CULTURE] Culture and [icon:YIELD_SCIENCE] Science per Age for each [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of."),
    ("en_US", "LOC_MOD_ATTRIBUTE_MILITARISTIC_01_DESCRIPTION", "+5 [icon:NAR_REW_COMBAT] Combat Strength against units belonging to Independent Powers and City-States. Whenever you defeat one of their units, gain [icon:YIELD_GOLD] Gold equal to 50% of its Combat Strength."),
    ("en_US", "LOC_MOD_ATTRIBUTE_MILITARISTIC_03_DESCRIPTION", "+100% [icon:YIELD_DIPLOMACY] Influence towards Levying Units from [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-States[/TIP]."),
    ("en_US", "LOC_MOD_ATTRIBUTE_MILITARISTIC_06_DESCRIPTION", "Garrisoned [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commanders[/TIP] provide +1 [icon:YIELD_SCIENCE] Science and +1 [icon:YIELD_CULTURE] Culture for each Commander Level.");
